/**
 * Refund processing.
 *
 * A refund is allowed only when the order exists, has not already been
 * refunded, and the total is at least 10.
 */

import { lookupOrder } from './order.service.js';

export class RefundError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'RefundError';
  }
}

export function refundOrder(orderId: string): void {
  const order = lookupOrder(orderId);

  if (order === undefined) {
    throw new RefundError(`Order ${orderId} not found`);
  }

  if (order.refunded) {
    throw new RefundError(`Order ${orderId} has already been refunded`);
  }

  if (order.total < 10) {
    throw new RefundError(`Order ${orderId} total ${order.total} is below minimum refund amount of 10`);
  }

  (order as any).refunded = true;
}

