 * Refund processing.
 *
 * A refund is allowed only when the order exists, has not already been
 * refunded, and the total is at least 10.
 */

import type { Result } from '../kernel/result.js';
import { err, ok } from '../kernel/result.js';
import { lookupOrder, markOrderRefunded } from './order.service.js';

export interface RefundError {
  readonly code: 'NOT_FOUND' | 'ALREADY_REFUNDED' | 'BELOW_MINIMUM';
  readonly message: string;
}

export function refundOrder(orderId: string): Result<void, RefundError> {
  const order = lookupOrder(orderId);

  if (order === undefined) {
    return err({
      code: 'NOT_FOUND',
      message: `Order ${orderId} not found`,
    });
  }

  if (order.refunded) {
    return err({
      code: 'ALREADY_REFUNDED',
      message: `Order ${orderId} has already been refunded`,
    });
  }

  if (order.total < 10) {
    return err({
      code: 'BELOW_MINIMUM',
      message: `Order ${orderId} total ${order.total} is below minimum refund amount of 10`,
    });
  }

  markOrderRefunded(order);
  return ok(undefined);
}

